function s(t){return`mp-session-${t.toUpperCase()}`}function r(t){return`mp-hostdata-${t.toUpperCase()}`}function o(t){try{sessionStorage.setItem(s(t.code),JSON.stringify(t))}catch{}}function i(t){try{let e=sessionStorage.getItem(s(t));if(!e)return null;let n=JSON.parse(e);if(typeof n.code=="string"&&typeof n.gameId=="string"&&typeof n.name=="string"&&typeof n.seat=="number"&&typeof n.playerId=="string"&&typeof n.playerToken=="string")return n}catch{}return null}function a(t){try{sessionStorage.removeItem(s(t)),sessionStorage.removeItem(r(t))}catch{}}function p(t,e){try{sessionStorage.setItem(r(t),JSON.stringify(e))}catch{}}function g(t){try{let e=sessionStorage.getItem(r(t));return e?JSON.parse(e):null}catch{return null}}function c(t){return typeof t.hostToken=="string"&&t.hostToken.length>0}export{o as a,i as b,a as c,p as d,g as e,c as f};
